"use client";

import { useCallback, useRef, useState } from "react";
import { createMemo, errorMessage, type MemoRecord } from "@/lib/api";
import type { RunView } from "@/lib/types";

/** A memo with the number of the request that asked for it: within one run, a later request's memo is never replaced. */
type Held = { memo: MemoRecord; asked: number };

/** The review memo for the current run: generated by the API from its stored, verified findings. */
export function useMemoAction() {
  // Memos are held by the run they were written for and shown only under that run (AssistantPanel): one that answers
  // after another run came on screen waits there for its own run (2026-10-13: a memo showed under the run gone back
  // to), and an older one answering late replaces neither another run's memo nor a newer one for its own (reviews).
  const [memos, setMemos] = useState<Record<string, Held>>({});
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  // Each request, and each reset (another run came on screen), is newer than the last: only the newest request still
  // standing sets the busy state and the error, so an older one failing or finishing says nothing about the screen.
  const requested = useRef(0);

  const generate = useCallback(async (run: RunView | null) => {
    if (!run || run.stage !== "complete") return;
    const asked = ++requested.current;
    setBusy(true);
    setError(null);
    try {
      const made = await createMemo(run.id);
      setMemos((held) => ((held[run.id]?.asked ?? 0) > asked ? held : { ...held, [run.id]: { memo: made, asked } }));
    } catch (e) {
      if (requested.current === asked) setError(errorMessage(e));
    } finally {
      if (requested.current === asked) setBusy(false);
    }
  }, []);

  const reset = useCallback(() => {
    requested.current++;
    setMemos({});
    setError(null);
    setBusy(false);
  }, []);

  const memoFor = useCallback((runId: string): MemoRecord | null => memos[runId]?.memo ?? null, [memos]);

  return { memoFor, busy, error, generate, reset };
}

export type MemoController = ReturnType<typeof useMemoAction>;
